{
  "seguradora": "AIG Seguros Brasil S.A.",
  "campos": {
    "limite_maximo_indenizacao": {
      "valor": null,
      "trecho": "O Limite Máximo de Garantia da Apólice é fixado com valor menor ou igual à soma dos limites máximos de indenizações estabelecidos individualmente para cada cobertura contratada",
      "pagina": "=== PÁGINA 4 ===",
      "observacao": "O valor é definido na Especificação da Apólice."
    },
    "franquia": {
      "valor": null,
      "trecho": "A importância definida na Especificação da Apólice, representando a participação da Sociedade ou do Segurado nos prejuízos consequentes dos Custos de Defesa e da Perda Indenizável.",
      "pagina": "=== PÁGINA 8 ===",
      "observacao": "O valor é definido na Especificação da Apólice."
    },
    "vigencia": {
      "valor": null,
      "trecho": "O Período de Vigência da Apólice será aquele indicado na Especificação da Apólice, sendo que, quando não houver adiantamento do Prêmio, seu início será a partir das 24 (vinte e quatro) horas do dia da aceitação da Proposta",
      "pagina": "=== PÁGINA 42 ===",
      "observacao": "O período é indicado na Especificação da Apólice."
    },
    "retroatividade": {
      "valor": null,
      "trecho": "Data igual ou anterior ao início da vigência da primeira de uma série sucessiva e ininterrupta de apólices de Seguro à Base de Reclamações, a ser pactuada pelas partes por ocasião da contratação inicial do seguro e indicada na Especificação da Apólice",
      "pagina": "=== PÁGINA 3 ===",
      "observacao": "A data é pactuada e indicada na Especificação da Apólice."
    },
    "prazo_complementar": {
      "valor": null,
      "trecho": "É a extensão de prazo para a apresentação de Reclamações, concedida pela Seguradora nos termos da cláusula Prazo Adicional, indicado na Especificação da Apólice e que pode ser estendido mediante endosso e pagamento do respectivo prêmio adicional.",
      "pagina": "=== PÁGINA 5 ===",
      "observacao": "O prazo é indicado na Especificação da Apólice."
    },
    "ambito_geografico": {
      "valor": "Mundial",
      "trecho": "Na medida legalmente permitida, esta Apólice cobrirá qualquer Reclamação realizada contra uma Parte Segurada em qualquer lugar do mundo , observado o disposto na cláusula Sanção, Embargo, Proibição ou Restrição Nacional ou Internacional",
      "pagina": "=== PÁGINA 33 ===",
      "observacao": null
    },
    "definicao_segurado": {
      "valor": "Conselheiros, Diretores, Empregados e indivíduos contratados por pessoa jurídica para exercer funções equivalentes, atuando em suas respectivas funções na Sociedade.",
      "trecho": "Qualquer pessoa física que seja, tenha sido ou se torne um: (i) Conselheiro ou Diretor de uma Sociedade desde que atuando em sua função na Sociedade; (ii) Empregado de uma Sociedade",
      "pagina": "=== PÁGINA 12 ===",
      "observacao": null
    },
    "custos_defesa": {
      "valor": "Incluídos no Limite Máximo de Garantia da Apólice.",
      "trecho": "Os Limites Máximos de Custos de Defesa são parte do valor e não em excesso ao Limite Máximo de Garantia da Apólice.",
      "pagina": "=== PÁGINA 4 ===",
      "observacao": null
    },
    "multas_administrativas": {
      "valor": "Cobertas se contratada a Cobertura Adicional específica, exceto multas contratuais, criminais ou impostas nos EUA.",
      "trecho": "a Seguradora pagará os Custos de Defesa de Reclamações cobertas sobre esta natureza e, a título de Perdas Indenizáveis, quaisquer multas ou penalidades cíveis ou administrativas impostas a um Segurado sempre que consideradas seguráveis pela legislação aplicável",
      "pagina": "=== PÁGINA 56 ===",
      "observacao": null
    },
    "exclusao_atos_dolosos": {
      "valor": "Excluídos atos ilícitos com dolo ou culpa grave equiparável ao dolo, fraude ou desonestidade, após decisão judicial ou confissão.",
      "trecho": "um ato ilícito cometido com dolo ou culpa grave equiparável ao dolo pel a Parte Segurada, beneficiário, sócios controladores, dirigentes e administradores legais ou pelo representante, de um ou de outro, ou com sua conivência, incluindo desonestidade e fraude",
      "pagina": "=== PÁGINA 27 ===",
      "observacao": null
    },
    "exclusao_ambiental": {
      "valor": "Excluídos danos ambientais, exceto se contratada a Cobertura Adicional de Responsabilidade por Danos Ambientais.",
      "trecho": "qualquer dano ambiental efetivo, suposto ou ameaçado , incluindo, mas não limita ndo a, descarga, dispensa, liberação ou vazamento de Poluentes, os registros e procedimentos de controle daqueles ou a qualquer ordem ou pedido para fazer testes",
      "pagina": "=== PÁGINA 28 ===",
      "observacao": null
    },
    "clausula_rescisao": {
      "valor": "Cancelamento por exaustão do limite, acordo entre partes, ou falta de pagamento do prêmio.",
      "trecho": "O presente contrato de seguro será cancelado: (i) quando a indenização ou a soma das indenizações pagas atingirem o Limite Máximo de Garantia da Apólice, não tendo o Tomador direito a qualquer restituição de Prêmio; ou (ii) total ou parcialmente, a qualquer tempo, mediante acordo entre as partes",
      "pagina": "=== PÁGINA 43 ===",
      "observacao": null
    },
    "definicao_reclamacao": {
      "valor": "Reivindicação escrita, processo judicial, administrativo, arbitral ou criminal contra um Segurado decorrente de Ato Danoso.",
      "trecho": "Uma reivindicação ou um requerimento escrito ou um processo judicial, administrativo ou arbitral, incluindo , mas não se limitando, àqueles de natureza cível, trabalhista, tributária, consumerista ou previdenciária ou de natureza criminal, contra um Segurado decorrente de um Ato Danoso",
      "pagina": "=== PÁGINA 11 ===",
      "observacao": null
    },
    "sublimites": {
      "valor": null,
      "trecho": "Os Limites Máximos de Indenização por Cobertura Contratada são parte do valor e não em excesso ao Limite Máximo de Garantia da Apólice.",
      "pagina": "=== PÁGINA 4 ===",
      "observacao": "Os sublimites são definidos na Especificação da Apólice para cada cobertura."
    },
    "cobertura_investigacoes": {
      "valor": "Cobertas se contratada a Extensão de Cobertura para Custos de Investigação.",
      "trecho": "A Seguradora pagará, até o Limite Máximo de Custos de Defesa e o Limite Máximo de Perdas Indenizáveis estabelecido na Especificação da Apólice, os custos, despesas e honorários [...] diretamente relacionadas à preparação para ou participação na Investigação.",
      "pagina": "=== PÁGINA 19 ===",
      "observacao": null
    }
  }
}
